	TranslateView_tmp_stream << "        } else {\n";
	TranslateView_tmp_stream << "            startCamera();\n";
	TranslateView_tmp_stream << "        }\n";
	TranslateView_tmp_stream << "    }\n";
TranslateView_tmp_stream<<"\n";
	TranslateView_tmp_stream << "    function startCamera() {\n";
	TranslateView_tmp_stream << "        navigator.mediaDevices.getUserMedia({ video: true })\n";
	TranslateView_tmp_stream << "            .then(stream => {\n";
	TranslateView_tmp_stream << "                cameraStream = stream;\n";
	TranslateView_tmp_stream << "                video.srcObject = stream;\n";
	TranslateView_tmp_stream << "                video.play().catch(e => console.error(\"Video play error:\", e));\n";
	TranslateView_tmp_stream << "                isTranslating = true;\n";
	TranslateView_tmp_stream << "                cameraText.innerText = \"Stop Camera\";\n";
	TranslateView_tmp_stream << "                cameraBtn.className = \"btn btn-dark\";\n";
	TranslateView_tmp_stream << "                placeholderText.style.display = \"none\";\n";
	TranslateView_tmp_stream << "                outputImage.style.display = \"block\";\n";
	TranslateView_tmp_stream << "                connectWebSocket();\n";
	TranslateView_tmp_stream << "            })\n";
	TranslateView_tmp_stream << "            .catch(err => {\n";
	TranslateView_tmp_stream << "                console.error(\"Camera error:\", err);\n";
	TranslateView_tmp_stream << "                alert(\"Camera error: \" + err.name + \" - \" + err.message + \"\\nAre you accessing via localhost?\");\n";
	TranslateView_tmp_stream << "            });\n";
	TranslateView_tmp_stream << "    }\n";
	TranslateView_tmp_stream << "    \n";
	TranslateView_tmp_stream << "    function stopCamera() {\n";
	TranslateView_tmp_stream << "        if (cameraStream) {\n";
	TranslateView_tmp_stream << "            cameraStream.getTracks().forEach(track => track.stop());\n";
	TranslateView_tmp_stream << "        }\n";
	TranslateView_tmp_stream << "        if (ws) {\n";
	TranslateView_tmp_stream << "            ws.close();\n";
	TranslateView_tmp_stream << "        }\n";
	TranslateView_tmp_stream << "        if (intervalId) {\n";
	TranslateView_tmp_stream << "            clearInterval(intervalId);\n";
	TranslateView_tmp_stream << "        }\n";
	TranslateView_tmp_stream << "        isTranslating = false;\n";
	TranslateView_tmp_stream << "        cameraText.innerText = \"Start Camera\";\n";
	TranslateView_tmp_stream << "        cameraBtn.className = \"btn btn-teal\";\n";
	TranslateView_tmp_stream << "        placeholderText.style.display = \"block\";\n";
	TranslateView_tmp_stream << "        outputImage.style.display = \"none\";\n";
	TranslateView_tmp_stream << "        statusBadge.className = \"status-badge\";\n";
	TranslateView_tmp_stream << "        statusBadge.innerText = \"Disconnected\";\n";
	TranslateView_tmp_stream << "        transText.innerText = \"...\";\n";
	TranslateView_tmp_stream << "    }\n";
TranslateView_tmp_stream<<"\n";
	TranslateView_tmp_stream << "    function connectWebSocket() {\n";
	TranslateView_tmp_stream << "        // Connect to Python WebSocket Server running on port 8000\n";
	TranslateView_tmp_stream << "        ws = new WebSocket('ws://localhost:8000/ws/translate');\n";
	TranslateView_tmp_stream << "        \n";
	TranslateView_tmp_stream << "        ws.onopen = () => {\n";
	TranslateView_tmp_stream << "            if(!isTranslating) {\n";
	TranslateView_tmp_stream << "                ws.close();\n";
	TranslateView_tmp_stream << "                return;\n";
	TranslateView_tmp_stream << "            }\n";
	TranslateView_tmp_stream << "            statusBadge.className = \"status-badge connected\";\n";
	TranslateView_tmp_stream << "            statusBadge.innerText = \"Connected to AI\";\n";
	TranslateView_tmp_stream << "            // Start sending frames (approx ~7 FPS)\n";
	TranslateView_tmp_stream << "            intervalId = setInterval(sendFrame, 150); \n";
	TranslateView_tmp_stream << "        };\n";
	TranslateView_tmp_stream << "        \n";
	TranslateView_tmp_stream << "        ws.onmessage = (event) => {\n";
	TranslateView_tmp_stream << "            const data = JSON.parse(event.data);\n";
	TranslateView_tmp_stream << "            if(data.image) {\n";
	TranslateView_tmp_stream << "                outputImage.src = \"data:image/jpeg;base64,\" + data.image;\n";
	TranslateView_tmp_stream << "            }\n";
	TranslateView_tmp_stream << "            if(data.translation && data.translation !== \"?\") {\n";
	TranslateView_tmp_stream << "                transText.innerText = data.translation;\n";
	TranslateView_tmp_stream << "            } else if (data.skeleton_found) {\n";
	TranslateView_tmp_stream << "                transText.innerText = \"Recognizing...\";\n";
	TranslateView_tmp_stream << "            } else {\n";
	TranslateView_tmp_stream << "                transText.innerText = \"No hand detected\";\n";
	TranslateView_tmp_stream << "            }\n";
	TranslateView_tmp_stream << "        };\n";
	TranslateView_tmp_stream << "        \n";
	TranslateView_tmp_stream << "        ws.onclose = () => {\n";
	TranslateView_tmp_stream << "            if (intervalId) clearInterval(intervalId);\n";
	TranslateView_tmp_stream << "            if(isTranslating) {\n";
	TranslateView_tmp_stream << "                statusBadge.className = \"status-badge\";\n";
	TranslateView_tmp_stream << "                statusBadge.innerText = \"Reconnecting...\";\n";
	TranslateView_tmp_stream << "                setTimeout(connectWebSocket, 3000); // Reconnect\n";
	TranslateView_tmp_stream << "            }\n";
	TranslateView_tmp_stream << "        };\n";
	TranslateView_tmp_stream << "    }\n";
TranslateView_tmp_stream<<"\n";
	TranslateView_tmp_stream << "    function sendFrame() {\n";
	TranslateView_tmp_stream << "        if(ws && ws.readyState === WebSocket.OPEN && video.readyState === video.HAVE_ENOUGH_DATA) {\n";
	TranslateView_tmp_stream << "            canvas.width = video.videoWidth;\n";
	TranslateView_tmp_stream << "            canvas.height = video.videoHeight;\n";
	TranslateView_tmp_stream << "            // Draw flipped video to match mirror effect\n";
	TranslateView_tmp_stream << "            ctx.translate(canvas.width, 0);\n";
	TranslateView_tmp_stream << "            ctx.scale(-1, 1);\n";
	TranslateView_tmp_stream << "            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);\n";
	TranslateView_tmp_stream << "            ctx.setTransform(1, 0, 0, 1, 0, 0); // reset transform\n";
	TranslateView_tmp_stream << "            \n";
	TranslateView_tmp_stream << "            // Get JPEG base64\n";
	TranslateView_tmp_stream << "            const dataUrl = canvas.toDataURL('image/jpeg', 0.6); \n";
	TranslateView_tmp_stream << "            ws.send(dataUrl);\n";
	TranslateView_tmp_stream << "        }\n";
	TranslateView_tmp_stream << "    }\n";
	TranslateView_tmp_stream << "</script>\n";
	TranslateView_tmp_stream << "</body>\n";
	TranslateView_tmp_stream << "</html>\n";
if(layoutName.empty())
{
std::string ret{std::move(TranslateView_tmp_stream.str())};
return ret;
}else
{
auto templ = DrTemplateBase::newTemplate(layoutName);
if(!templ) return "";
HttpViewData data = TranslateView_view_data;
auto str = std::move(TranslateView_tmp_stream.str());
if(!str.empty() && str[str.length()-1] == '\n') str.resize(str.length()-1);
data[""] = std::move(str);
return templ->genText(data);
}
